const fs = require('fs');
const path = '.v1/state.json';
const raw = fs.readFileSync(path, 'utf-8');
const s = JSON.parse(raw);

// Set phase to diagnosis (reflecting where we are tracking a hypothesis)
s.phase = 'diagnosis';

s.hypotheses = s.hypotheses || [];
// Remove any prior entries with same id (idempotent)
s.hypotheses = s.hypotheses.filter(h => h.id !== 'hyp-12d74b0b');
s.hypotheses.push({
  id: 'hyp-12d74b0b',
  description: 'Root cause: dequeue() in src/queue.ts uses Array.shift() which returns undefined for an empty queue, then casts it to Job<T> via `as Job<T>` and returns that undefined value to the caller instead of throwing. Fix: detect the falsy shift result and throw an Error whose message matches /empty/i (per tests/queue.test.ts:14-18).',
  evidence: [
    'src/queue.ts:36-39: dequeue() body — `const job = this.queue.shift(); return job as Job<T>;` (the BUG comment and unsafe cast are diagnostic)',
    'tests/queue.test.ts:14-18: `expect(() => q.dequeue()).toThrow(/empty/i)` documents expected behavior',
    'src/queue.ts:104-110: processNext() guards with `if (this.queue.length === 0) return null;` BEFORE calling dequeue(), confirming the rest of the codebase assumes dequeue on empty is exceptional',
    'src/queue.ts:71-74: peek() correctly returns `Job<T> | undefined`, demonstrating the author distinguished peek (may be empty) from dequeue (should never be empty)'
  ],
  confidence: 0.97,
  status: 'selected',
  files: ['src/queue.ts', 'tests/queue.test.ts']
});
s.selectedHypothesis = 'hyp-12d74b0b';

fs.writeFileSync(path, JSON.stringify(s, null, 2));

// Re-read to confirm persistence
const verify = JSON.parse(fs.readFileSync(path, 'utf-8'));
console.log('phase:', verify.phase);
console.log('hypotheses count:', verify.hypotheses.length);
console.log('selected:', verify.selectedHypothesis);
console.log('first hyp id:', verify.hypotheses[0] && verify.hypotheses[0].id);
console.log('first hyp status:', verify.hypotheses[0] && verify.hypotheses[0].status);
console.log('first hyp confidence:', verify.hypotheses[0] && verify.hypotheses[0].confidence);
console.log('first hyp files:', JSON.stringify(verify.hypotheses[0] && verify.hypotheses[0].files));
"
